use nameslib::*;


use std::alloc::{GlobalAlloc, Layout, System};
use std::cell::Cell;

struct Counting;

thread_local! {
    static COUNT: Cell<usize> = const { Cell::new(0) };
    static ON: Cell<bool> = const { Cell::new(false) };
}

fn bump() {
    ON.with(|on| {
        if on.get() {
            COUNT.with(|c| c.set(c.get() + 1));
        }
    });
}

unsafe impl GlobalAlloc for Counting {
    unsafe fn alloc(&self, l: Layout) -> *mut u8 {
        bump();
        System.alloc(l)
    }
    unsafe fn dealloc(&self, p: *mut u8, l: Layout) {
        System.dealloc(p, l)
    }
    unsafe fn realloc(&self, p: *mut u8, l: Layout, n: usize) -> *mut u8 {
        bump();
        System.realloc(p, l, n)
    }
}

#[global_allocator]
static A: Counting = Counting;

fn allocs<T>(f: impl FnOnce() -> T) -> (T, usize) {
    COUNT.with(|c| c.set(0));
    ON.with(|o| o.set(true));
    let r = f();
    ON.with(|o| o.set(false));
    (r, COUNT.with(|c| c.get()))
}

struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        self.0 = self.0.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        self.0 >> 33
    }
    fn below(&mut self, n: u64) -> u64 {
        self.next() % n
    }
}

fn reference(a: &str, b: &str) -> bool {
    a.to_lowercase() == b.to_lowercase()
}
fn small_input(r: &mut Rng) -> (String, String) {
    let words = ["Harbour", "HARBOUR", "harbour", "Kiln", "kiln", "KILN", "Tide", "tide"];
    (words[r.below(8) as usize].to_string(), words[r.below(8) as usize].to_string())
}
fn big_input(_r: &mut Rng) -> (String, String) {
    ("HARBOUR-MASTER-OFFICE".to_string(), "harbour-master-office".to_string())
}
fn call_it(input: &(String, String)) -> bool { same_name(&input.0, &input.1) }
fn ref_it(input: &(String, String)) -> bool { reference(&input.0, &input.1) }

#[test]
fn behaviour_matches_reference() {
    let mut r = Rng(40);
    for _ in 0..300 {
        let input = small_input(&mut r);
        assert_eq!(call_it(&input), ref_it(&input), "input {:?}", input);
    }
}

#[test]
fn allocs_stay_low() {
    let mut r = Rng(40);
    let input = big_input(&mut r);
    let (got, n) = allocs(|| call_it(&input));
    assert!(n <= 0, "PERF: {} allocations per call (limit 0): the function allocates much more than it needs to", n);
    assert_eq!(got, ref_it(&input));
}

